local ServiceResolverManager = require(script.Parent.ServiceResolverManager)
local ServiceCollection = require(script.Parent.ServiceCollection)

return function()
	describe("ServiceResolverManager", function()
		it("应该能够正确创建实例", function()
			local manager = ServiceResolverManager.new()
			expect(manager).to.be.ok()
		end)

		it("应该在服务不存在时抛出错误", function()
			local manager = ServiceResolverManager.new()
			expect(function()
				manager:resolve("NonExistentService")
			end).to.throw()
		end)
	end)
end
